            for i in range(len(demands)):
                demand_map[i] = demands[i]
        except:
            pass

    def demand_of(c):
        if c == depot:
            return 0
        if c in demand_map:
            return demand_map[c]
        return 1

    if capacity is None:
        total = 0
        for c in customers:
            total += demand_of(c)
        capacity = total if total > 0 else max(1, len(customers))

    coord_map = {}
    if isinstance(coords, dict):
        for k in coords:
            coord_map[k] = coords[k]
    elif coords is not None:
        try:
            for i in range(len(coords)):
                coord_map[i] = coords[i]
        except:
            pass

    def point_of(c):
        if c in coord_map:
            return coord_map[c]
        return None

    def dist(a, b):
        pa = point_of(a)
        pb = point_of(b)
        if pa is None or pb is None:
            da = a - b
            if da < 0:
                da = -da
            return da
        ax = pa[0]
        ay = pa[1]
        bx = pb[0]
        by = pb[1]
        dx = ax - bx
        dy = ay - by
        return (dx * dx + dy * dy) ** 0.5

    depot_pt = point_of(depot)
    if depot_pt is not None:
        dx0 = depot_pt[0]
        dy0 = depot_pt[1]

        def angle_key(c):
            p = point_of(c)
            if p is None:
                return (10, 0, demand_of(c), c)
            x = p[0] - dx0
            y = p[1] - dy0
            if x == 0 and y == 0:
                ang = -1
            elif x >= 0 and y >= 0:
                ang = 0 + (y / (x + y + 1e-12))
            elif x < 0 <= y:
                ang = 1 + ((-x) / ((-x) + y + 1e-12))
            elif x <= 0 and y < 0:
                ang = 2 + ((-y) / ((-x) + (-y) + 1e-12))
            else:
                ang = 3 + (x / (x + (-y) + 1e-12))
            r = x * x + y * y
            return (ang, r, demand_of(c), c)

        ordered = sorted(customers, key=angle_key)
    else:
        ordered = sorted(customers, key=lambda c: (demand_of(c), c))

    unserved = set(customers)
    routes = []

    while unserved:
        route = []
        load = 0
        current = depot
        seed = None
        seed_key = None
        for c in ordered:
            if c in unserved:
                d = demand_of(c)
                if load + d <= capacity:
                    k = (dist(depot, c), d, c)
                    if seed is None or k < seed_key:
                        seed = c
                        seed_key = k
        if seed is not None:
            route.append(seed)
            unserved.remove(seed)
            load += demand_of(seed)
            current = seed

        while True:
            best = None
            best_key = None
            for c in ordered:
                if c not in unserved:
                    continue
                d = demand_of(c)
                if load + d > capacity:
                    continue
                k = (dist(current, c), d, c)
                if best is None or k < best_key:
                    best = c
                    best_key = k
            if best is None:
                break
            route.append(best)
            unserved.remove(best)
            load += demand_of(best)
            current = best

        if not route and unserved:
            c = None
            for x in ordered:
                if x in unserved:
                    c = x
                    break
            if c is None:
                c = next(iter(unserved))
            route = [c]
            unserved.remove(c)

        routes.append(route)

    routes = [r for r in routes if r]

    def route_load(rt):
        s = 0
        for c in rt:
            s += demand_of(c)
        return s

    def route_length(rt):
        if not rt:
            return 0
        total = dist(depot, rt[0])
        for i in range(len(rt) - 1):
            total += dist(rt[i], rt[i + 1])
        total += dist(rt[-1], depot)
        return total

    for idx in range(len(routes)):
        rt = routes[idx]
        if len(rt) < 3:
            continue
        improved = True
        while improved:
            improved = False
            best_rt = rt
            best_len = route_length(rt)
            n = len(rt)
            for i in range(n - 1):
                for j in range(i + 1, n):
                    cand = rt[:]
                    cand[i], cand[j] = cand[j], cand[i]
                    clen = route_length(cand)
                    if clen + 1e-12 < best_len:
                        best_len = clen
                        best_rt = cand
                        improved = True
            rt = best_rt
        routes[idx] = rt

    seen = set()
    final_routes = []
    for rt in routes:
        nr = []
        load = 0
        for c in rt:
            if c == depot or c in seen:
                continue
            d = demand_of(c)
            if load + d <= capacity:
                nr.append(c)
                load += d
                seen.add(c)
        if nr:
            final_routes.append(nr)

    missing = []
    for c in customers:
        if c not in seen:
            missing.append(c)

    for c in missing:
        d = demand_of(c)
        placed = False
        best_route = None
        best_pos = None
        best_cost = None
        for ri in range(len(final_routes)):
            rt = final_routes[ri]
            if route_load(rt) + d > capacity:
                continue
            for pos in range(len(rt) + 1):
                cand = rt[:pos] + [c] + rt[pos:]
                cost = route_length(cand)
                if best_cost is None or cost < best_cost or (cost == best_cost and (ri, pos, c) < (best_route, best_pos, c)):
                    best_cost = cost
                    best_route = ri
                    best_pos = pos
        if best_route is not None:
            rt = final_routes[best_route]
            final_routes[best_route] = rt[:best_pos] + [c] + rt[best_pos:]
            seen.add(c)
            placed = True
        if not placed:
            final_routes.append([c])
            seen.add(c)

    return final_routes
